<?php declare(strict_types=1);

function tie_round(array $types): Closure {
    $given=array_fill_keys($types,false);
    return function($b)use(&$given,$types){foreach($types as $t) if(!$given[$t]&&in_array($t,[$b['left_var'],$b['right_var']],true)){$given[$t]=true;return [$b['left_var']===$t?'left':'right',1];}return ['neutral',0];};
}
function invite_fixture(string $dir,string $status='sent',?string $expires=null): void {
    file_put_contents($dir.'/data/invites.json',json_encode([['id'=>'http-invite','code'=>'HTTPTEST','token'=>'http-token','status'=>$status,'guess_type'=>'7','guess_prob'=>'80','expires_at'=>$expires]]));
}
function assert_technical(Participant $p): void {
    verify(($p->s['state']??'')==='phase2_unresolved','Explicit TECHNICAL_ERROR state');
    verify(!str_contains($p->html,'TYYLI ')&&!str_contains($p->html,'Testisi on suoritettu'),'Technical failure is not a completed personality result');
    verify(($p->s['log_row']['finalVar']??'')!=='RATKAISEMATON','Technical failure is not UNRESOLVED_TIE');
    foreach(research_rows($p->dir) as $r) verify($r['session_id']!==$p->cookie,'No technical failure research result');
}

// Independent direct CSV expectation: every field and group attribution in the loader.
$raw=[];$fp=fopen($sandbox.'/SeparateBlocksQuestionsTiebreak.csv','r');
while(($row=fgetcsv($fp,0,';','"','\\'))!==false) if(count($row)>=6&&ctype_digit(trim($row[0]))&&preg_match('/^([ABCD])vs([ABCD])$/',$row[1],$m)) $raw[trim($row[0])]=['pair'=>[$m[1],$m[2]],'statement'=>trim($row[3]),'left'=>trim($row[4]),'right'=>trim($row[5])];
fclose($fp);$p1pairs=[];foreach($raw as $r){$key=implode('-',$r['pair']);$p1pairs[$key]=($p1pairs[$key]??0)+1;}
scenario('Phase1 CSV: all 42 rows, six pairs, seven comparisons each',function()use($raw,$p1pairs){verify(count($raw)===42&&count($p1pairs)===6,'42 rows / six pairs');foreach($p1pairs as $n)verify($n===7,'Seven questions per Phase1 pair');});
foreach($p1pairs as $key=>$count) foreach(explode('-',$key) as $winner) scenario("Phase1 pair $key winner $winner, navigation -> Phase2 -> result",function()use($base,$sandbox,$key,$count,$winner,$raw,$groups){
    $pair=explode('-',$key);$p=new Participant($base,$sandbox);$p->begin();$v=array_fill_keys(['A1','B1','C1','D1'],1);foreach($pair as $g)$v[$g.'1']=5;$p->phase1($v);
    verify($p->s['state']==='tb1_new_intro','Phase1 tie -> new tiebreak intro');
    $loaded=$p->s['cached_tb1_new_blocks'];verify(count($loaded)===count($raw),'Loader reads every valid row');
    foreach($loaded as $b){$r=$raw[$b['question_num']];verify([$b['block_left'],$b['block_right']]===$r['pair']&&$b['statement']===$r['statement']&&$b['option_left']===$r['left']&&$b['option_right']===$r['right'],'Original CSV fields and attribution preserved');}
    verify(count($p->s['tb1_new_questions'])===$count,'All selected pair questions');
    foreach($p->s['tb1_new_questions'] as $b){$r=$raw[$b['question_num']];foreach(['left','right'] as $side){$originalSide=$b['block_'.$side]===$r['pair'][0]?'left':'right';verify($b['option_'.$side]===$r[$originalSide],'Randomized option still belongs to correct group');}}
    $p->submit(['continue_tb1_new'=>'1']);$seen=[];$n=0;
    while($p->s['state']==='tb1_new'){
        $b=$p->s['tb1_new_questions'][$p->s['tb1_new_index']];
        verify(str_contains($p->html,htmlspecialchars($b['statement'],ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')),'TB1 statement rendered');
        $seen[$b['question_num']]=true;$p->submit(['tb1_new_choice'=>$winner]);$n++;
        if($n===2){$p->submit(['tb1_new_navigate'=>'back']);verify($p->s['tb1_new_index']===1&&count($p->s['tb1_new_answers'])===1,'Back removes previous answer');$other=$pair[0]===$winner?$pair[1]:$pair[0];$p->submit(['tb1_new_choice'=>$other]);$p->submit(['tb1_new_navigate'=>'back']);$p->submit(['tb1_new_choice'=>$winner]);}
        $expected=array_fill_keys(['A','B','C','D'],0);foreach($p->s['tb1_new_answers'] as $a)$expected[substr($a,-1)]++;
        verify($p->s['tb1_new_counters']===$expected,'Exactly one point per current answer, no navigation duplicates');
        verify(count($p->s['tb1_new_answers'])===$n,'One record per question');
    }
    verify(count($seen)===$count&&$p->s['tb1_new_counters'][$winner]===$count,'All comparisons asked once after revisions');
    $track=$winner.'2';verify($p->s['track']===$track&&$p->s['state']==='phase2_intro','Correct track; no A1 shortcut');
    $target=$groups[$track][0];$p->phase2(favor($target));$r=$p->finish($target);
    foreach($p->s['tb1_new_answers'] as $i=>$a)verify($r['TB1_'.($i+1)]===$a,'TB1 answer code persisted');
    foreach(['A','B','C','D'] as $g)verify((int)$r[$g.'1_tb1_counter']===$p->s['tb1_new_counters'][$g],'TB1 counters persisted');
});

foreach($groups as $track=>$types) scenario("legacy Phase1 tiebreak -> $track full workflow",function()use($base,$sandbox,$track,$types){
    $winner=$track[0].'1';$other=$winner==='A1'?'B1':'A1';$p=new Participant($base,$sandbox);$p->begin('Legacy','','oldTB1=1');$v=array_fill_keys(['A1','B1','C1','D1'],1);$v[$winner]=$v[$other]=5;$p->phase1($v);verify($p->s['state']==='tiebreak_intro','Legacy intro');$p->submit(['continue_tiebreak'=>'1']);$n=0;
    while($p->s['state']==='tiebreak'){$q=$p->s['tiebreak_set'][$p->s['tiebreak_index']];$p->submit(['tb_choice'=>$q['class']===$winner?'6':'1']);$n++;if($n===2){$points=$p->s['tiebreak_points'];$p->submit(['tiebreak_navigate'=>'back']);$q=$p->s['tiebreak_set'][$p->s['tiebreak_index']];$p->submit(['tb_choice'=>$q['class']===$winner?'6':'1']);verify($p->s['tiebreak_points']===$points,'Legacy replacement does not duplicate points');}}
    verify($p->s['track']===$track,'Legacy winner reaches correct track');$p->phase2(favor($types[0]));$p->finish($types[0]);
});

scenario('Three-group near tie selects existing top-two policy',function()use($base,$sandbox){$p=new Participant($base,$sandbox);$p->begin();$p->phase1(['A1'=>5,'B1'=>5,'C1'=>5,'D1'=>1]);verify($p->s['tiebreak_classes']===['A1','B1'],'Existing three-way Phase1 policy selects two; no algorithm change');});
scenario('Three-group close scores 47-46-45 retain top-two policy',function()use($base,$sandbox){$p=new Participant($base,$sandbox);$p->begin();$a=$b=0;$p->phase1(['A1'=>function()use(&$a){return $a++<2?6:5;},'B1'=>function()use(&$b){return $b++<1?6:5;},'C1'=>5,'D1'=>1]);verify($p->s['points1']['A1']===47&&$p->s['points1']['B1']===46&&$p->s['points1']['C1']===45&&$p->s['tiebreak_classes']===['A1','B1'],'47-46-45 picks existing first two only');});
scenario('Phase1 equal TB counters use existing Phase1 score fallback',function()use($base,$sandbox,$originals){
    configure($sandbox,'SeparateBlocksQuestionsTiebreak.csv',preg_replace('/^7;BvsC;.*\R?/m','',$originals['SeparateBlocksQuestionsTiebreak.csv']));
    try{$p=new Participant($base,$sandbox);$p->begin();$first=true;$p->phase1(['A1'=>1,'B1'=>function()use(&$first){$v=$first?6:5;$first=false;return $v;},'C1'=>5,'D1'=>1]);verify($p->s['points1']['B1']===46&&$p->s['points1']['C1']===45,'One-point close score enters tiebreak');$p->submit(['continue_tb1_new'=>'1']);$n=0;while($p->s['state']==='tb1_new')$p->submit(['tb1_new_choice'=>$n++%2?'B':'C']);verify($p->s['tb1_new_counters']['B']===3&&$p->s['tb1_new_counters']['C']===3&&$p->s['track']==='B2','Counter tie uses higher original score');$p->phase2(favor('3'));$p->finish('3');}finally{configure($sandbox,'SeparateBlocksQuestionsTiebreak.csv',$originals['SeparateBlocksQuestionsTiebreak.csv']);}
});
scenario('Phase1 answer revision replaces score and record',function()use($base,$sandbox){$p=new Participant($base,$sandbox);$p->begin();$q=$p->s['phase1'][0];$p->submit(['choice'=>'6']);$p->submit(['navigate'=>'prev']);$p->submit(['choice'=>'2']);verify($p->s['q1_index']===1&&$p->s['points1'][$q['class']]===2&&count($p->s['answers1'])===1&&$p->s['yesCounts1'][$q['class']]===0,'Revision replaces prior answer and yes-count');});
scenario('TB1 rejects group outside current comparison',function()use($base,$sandbox){$p=new Participant($base,$sandbox);$p->begin();$p->phase1(['A1'=>5,'B1'=>5,'C1'=>1,'D1'=>1]);$p->submit(['continue_tb1_new'=>'1']);$before=$p->s;$p->submit(['tb1_new_choice'=>'C']);verify($p->s['tb1_new_index']===$before['tb1_new_index']&&$p->s['tb1_new_counters']===$before['tb1_new_counters'],'Out-of-pair choice rejected');});

foreach($groups as $track=>$types){
    scenario("$track positive three-way tie retains accumulated scores HTTP",function()use($base,$sandbox,$track,$types){$p=new Participant($base,$sandbox);$p->reach($track);$p->phase2(tie_round($types));verify($p->s['varPoints']==array_fill_keys($types,1),'All three start TB with positive equal points');$p->tb2(favor($types[2]));$p->finish($types[2]);});
    for($i=0;$i<3;$i++)for($j=$i+1;$j<3;$j++)foreach(['decisive','unresolved'] as $outcome)scenario("$track pair {$types[$i]}-{$types[$j]} $outcome HTTP",function()use($base,$sandbox,$track,$types,$i,$j,$outcome){$pair=[$types[$i],$types[$j]];$p=new Participant($base,$sandbox);$p->reach($track);$p->phase2(tie_round($pair));verify($p->s['state']==='phase2_tb'&&$p->s['tb2_pair']===$pair,'Two actual leaders');foreach($p->s['tb2_set'] as $b){$a=$b['pair'];sort($a);verify($a===$pair,'Only requested pair');}$p->tb2($outcome==='decisive'?favor($pair[0]):neutral());$p->finish($outcome==='decisive'?$pair[0]:'RATKAISEMATON');});
    foreach($types as $target)scenario("$track three-way neutral -> decisive $target HTTP",function()use($base,$sandbox,$track,$target){$p=new Participant($base,$sandbox);$p->reach($track);$p->phase2(neutral());$expected=$p->s['cached_quiz_data']['phase2_tiebreaks']['T'.$track];verify(count($p->s['tb2_set'])===count($expected),'All configured three-way questions');$p->tb2(favor($target));$p->finish($target);});
    foreach([2,3] as $leaders)scenario("$track three-way -> $leaders remaining leaders HTTP",function()use($base,$sandbox,$track,$types,$leaders){$p=new Participant($base,$sandbox);$p->reach($track);$p->phase2(neutral());$tied=$leaders===2?array_slice($types,1):$types;$p->tb2($leaders===2?tie_round($tied):neutral());verify($p->s['log_row']['tied_types']===$tied,'Only final highest types');$p->finish('RATKAISEMATON');});
}

foreach(['token','code'] as $mode)foreach(['normal','unresolved'] as $outcome)scenario("invited $mode $outcome full HTTP",function()use($base,$sandbox,$mode,$outcome){invite_fixture($sandbox);$p=new Participant($base,$sandbox);$p->begin('Kutsuttu',$mode==='code'?'HTTPTEST':'',$mode==='token'?'invite=http-token':'');verify(json_decode(file_get_contents($sandbox.'/data/invites.json'),true)[0]['status']==='accepted','Invite accepted');$p->phase1(['D1'=>6,'A1'=>1,'B1'=>1,'C1'=>1]);$p->phase2($outcome==='normal'?favor('9'):neutral());if($outcome==='unresolved')$p->tb2(neutral());$r=$p->finish($outcome==='normal'?'9':'RATKAISEMATON');verify($r['invite_id']==='http-invite'&&$r['invited']==='Kyllä'&&$r['ref_guess']==='7','Invitation research metadata retained');verify(json_decode(file_get_contents($sandbox.'/data/invites.json'),true)[0]['status']==='completed','Completed normal/unresolved invitation');});
foreach(['invalid','expired','completed','past-expiry'] as $mode)scenario("invitation rejected $mode",function()use($base,$sandbox,$mode){invite_fixture($sandbox,$mode==='past-expiry'?'sent':($mode==='invalid'?'sent':$mode),$mode==='past-expiry'?'2000-01-01 00:00:00':null);$p=new Participant($base,$sandbox);$p->submit(['start'=>'1','nickname'=>'Invalid','ennea'=>'en tiedä','invite_code'=>$mode==='invalid'?'BOGUS':'HTTPTEST']);verify($p->s['state']==='intro'&&empty($p->s['InviteId']),'Invalid/expired/completed code rejected');});

foreach(['invalid','expired','completed','past-expiry'] as $mode) scenario("invitation token rejected $mode",function()use($base,$sandbox,$mode){invite_fixture($sandbox,$mode==='past-expiry'?'sent':($mode==='invalid'?'sent':$mode),$mode==='past-expiry'?'2000-01-01 00:00:00':null);$p=new Participant($base,$sandbox);$p->request('/index.php?invite='.($mode==='invalid'?'BOGUS':'http-token'));verify($p->s['state']==='intro'&&empty($p->s['InviteId']),'Invalid/expired/completed token rejected');});
scenario('Missing TB1 file falls back to configured legacy questions',function()use($base,$sandbox,$originals){configure($sandbox,'SeparateBlocksQuestionsTiebreak.csv',null);try{$p=new Participant($base,$sandbox);$p->begin();$p->phase1(['A1'=>5,'B1'=>5,'C1'=>1,'D1'=>1]);verify($p->s['state']==='tiebreak_intro'&&count($p->s['tiebreak_set'])===6,'Existing fallback to six valid legacy questions');$p->submit(['continue_tiebreak'=>'1']);while($p->s['state']==='tiebreak'){$q=$p->s['tiebreak_set'][$p->s['tiebreak_index']];$p->submit(['tb_choice'=>$q['class']==='A1'?'6':'1']);}$p->phase2(favor('4'));$p->finish('4');}finally{configure($sandbox,'SeparateBlocksQuestionsTiebreak.csv',$originals['SeparateBlocksQuestionsTiebreak.csv']);}});
foreach([false,true] as $breakLegacy) scenario('Missing selected Phase1 pair '.($breakLegacy?'without legacy fails safely':'uses valid legacy fallback'),function()use($base,$sandbox,$originals,$breakLegacy){
    configure($sandbox,'SeparateBlocksQuestionsTiebreak.csv',preg_replace('/^\d+;AvsB;.*\R?/m','',$originals['SeparateBlocksQuestionsTiebreak.csv']));
    if($breakLegacy)configure($sandbox,'SeparateBlocksQuestions.csv',preg_replace('/^[AB]11;.*\R?/m','',$originals['SeparateBlocksQuestions.csv']));
    try{$p=new Participant($base,$sandbox);$p->begin();$p->phase1(['A1'=>5,'B1'=>5,'C1'=>1,'D1'=>1]);
        verify(count($p->s['cached_tb1_new_blocks'])===35,'Other five new pairs remain configured');
        if($breakLegacy){assert_technical($p);return;}
        verify($p->s['state']==='tiebreak_intro'&&count($p->s['tiebreak_set'])===6,'Selected pair uses valid existing fallback');
        $p->submit(['continue_tiebreak'=>'1']);while($p->s['state']==='tiebreak'){$q=$p->s['tiebreak_set'][$p->s['tiebreak_index']];$p->submit(['tb_choice'=>$q['class']==='A1'?'6':'1']);}
        $p->phase2(favor('9'));$p->finish('9');
    }finally{foreach($originals as $f=>$c)configure($sandbox,$f,$c);}
});
scenario('Missing both Phase1 tiebreak sources fails safely',function()use($base,$sandbox,$originals){configure($sandbox,'SeparateBlocksQuestionsTiebreak.csv',"1;AvsA;bad;statement;left;right\ninvalid;AvsB;bad;statement;left;right\n");configure($sandbox,'SeparateBlocksQuestions.csv',preg_replace('/^[ABCD]11;.*\R?/m','',$originals['SeparateBlocksQuestions.csv']));try{$p=new Participant($base,$sandbox);$p->begin();$p->phase1(['A1'=>5,'B1'=>5,'C1'=>1,'D1'=>1]);assert_technical($p);}finally{foreach($originals as $f=>$c)configure($sandbox,$f,$c);}});
scenario('Missing Phase2 TB pair: accepted invite remains uncompleted',function()use($base,$sandbox,$originals){$p=new Participant($base,$sandbox);invite_fixture($sandbox);configure($sandbox,'InsideBlockQuestions.csv',preg_replace('/^TA2(?:-4vs7|a-4|b-7);.*\R?/m','',$originals['InsideBlockQuestions.csv']));try{$p->begin('Failure','HTTPTEST');$p->phase1(['A1'=>6,'B1'=>1,'C1'=>1,'D1'=>1]);$p->phase2(neutral());assert_technical($p);verify(json_decode(file_get_contents($sandbox.'/data/invites.json'),true)[0]['status']==='accepted','Technical error does not complete invite');}finally{configure($sandbox,'InsideBlockQuestions.csv',$originals['InsideBlockQuestions.csv']);}});
scenario('Invalid Phase2 tags and empty question set fail safely',function()use($base,$sandbox,$originals){configure($sandbox,'InsideBlockQuestions.csv',"INVALID;1;bad\nA2a-4;2;left\nA2b-7;3;right\n");try{$p=new Participant($base,$sandbox);$p->begin();$p->phase1(['A1'=>6,'B1'=>1,'C1'=>1,'D1'=>1]);assert_technical($p);}finally{configure($sandbox,'InsideBlockQuestions.csv',$originals['InsideBlockQuestions.csv']);}});
scenario('Unexpected group and missing session data fail safely',function()use($base,$sandbox){foreach([['track'=>'Z2'],['blocks2'=>null],['varCodes'=>null],['varPoints'=>null]] as $patch){$p=new Participant($base,$sandbox);$p->reach('A2');$p->corrupt(array_merge(['state'=>'phase2'],$patch));assert_technical($p);}});
scenario('Invalid Phase2 values do not advance or corrupt points',function()use($base,$sandbox){$p=new Participant($base,$sandbox);$p->reach('A2');$p->submit(['continue_phase2'=>'1']);foreach([['3','left'],['x','left'],['2','neutral'],['0','right'],['2','bogus']] as [$v,$side]){$before=$p->s;$p->submit(['choice2_value'=>$v,'choice2_side'=>$side]);verify($p->s['q2_index']===$before['q2_index']&&$p->s['varPoints']===$before['varPoints'],'Invalid or inconsistent answer rejected');}});
scenario('Stale POST rejected at Phase2 and Phase2 tiebreak steps',function()use($base,$sandbox){$p=new Participant($base,$sandbox);$p->reach('A2');$p->submit(['continue_phase2'=>'1']);$p->submit(['choice2_value'=>'0','choice2_side'=>'neutral']);$before=$p->s;$p->request('/index.php',$p->lastPost);verify($p->s['q2_index']===$before['q2_index']&&$p->s['pairs2']===$before['pairs2'],'Repeated standard answer rejected');while($p->s['state']==='phase2')$p->submit(['choice2_value'=>'0','choice2_side'=>'neutral']);$p->submit(['tb2_value'=>'0','tb2_side'=>'neutral']);$before=$p->s;$p->request('/index.php',$p->lastPost);verify($p->s['tb2_index']===$before['tb2_index']&&$p->s['tb2_pairs']===$before['tb2_pairs'],'Repeated TB2 answer rejected');});
scenario('Stale POST rejected at new and legacy Phase1 tiebreak steps',function()use($base,$sandbox){foreach([false,true] as $legacy){$p=new Participant($base,$sandbox);$p->begin('Retry','',$legacy?'oldTB1=1':'');$p->phase1(['A1'=>5,'B1'=>5,'C1'=>1,'D1'=>1]);$p->submit([$legacy?'continue_tiebreak':'continue_tb1_new'=>'1']);$p->submit($legacy?['tb_choice'=>'6']:['tb1_new_choice'=>'A']);$before=$p->s;$p->request('/index.php',$p->lastPost);$index=$legacy?'tiebreak_index':'tb1_new_index';$answers=$legacy?'tiebreak_answers':'tb1_new_answers';verify($p->s[$index]===$before[$index]&&$p->s[$answers]===$before[$answers],'Retry does not answer another TB1 question');}});
scenario('Reset, new cookies, interrupted session and unsupported POST',function()use($base,$sandbox){$a=new Participant($base,$sandbox);$b=new Participant($base,$sandbox);verify($a->cookie!==$b->cookie,'New session isolation');$a->begin();$a->submit(['choice'=>'6']);verify($b->s['state']==='intro','Other cookie unchanged');$a->request('/index.php?reset=1');verify($a->s['state']==='intro'&&empty($a->s['answers1']),'Reset clean session');$a->submit(['continue_phase2'=>'1']);verify($a->s['state']==='intro','Unsupported transition rejected');$a->cookie='';$a->request();verify($a->s['state']==='intro','Session interruption starts new intro');});
scenario('Question cache refresh after actual CSV change',function()use($base,$sandbox,$originals){$p=new Participant($base,$sandbox);$p->begin();$old=$p->s['cached_quiz_data']['phase2_blocks']['A2'][0]['desc'];$changed=str_replace($old,$old.' TEST-CACHE-CHANGE',$originals['InsideBlockQuestions.csv']);configure($sandbox,'InsideBlockQuestions.csv',$changed);try{$p->request('/index.php?reset=1');$p->begin();verify(str_contains($p->s['cached_quiz_data']['phase2_blocks']['A2'][0]['desc'],'TEST-CACHE-CHANGE'),'Fresh session loads modified CSV');}finally{configure($sandbox,'InsideBlockQuestions.csv',$originals['InsideBlockQuestions.csv']);}});
